import assert from 'node:assert/strict';
import { createAgenticDecider } from './apps/desktop/src/main/agentic-decider.ts';

let capturedOptions = null;
const fakeLlm = {
  async generate(_messages, options) {
    capturedOptions = options;
    return {
      text: '{"action":"done","success":false,"reason":"test","evidence":"test"}',
      model: 'fake',
      raw: { responseId: 'resp_test' }
    };
  }
};

const decider = createAgenticDecider(fakeLlm, { vision: true, reasoningEffort: 'low', maxTokens: 123 });
const result = await decider.decide({
  goal: 'Open example.com',
  successCriteria: 'Example Domain is visible',
  stepIndex: 7,
  maxSteps: 10,
  url: 'https://example.com',
  title: 'Example Domain',
  pageText: 'Example Domain',
  screenshotBase64: Buffer.from('fake-image').toString('base64'),
  history: [],
  previousResponseId: 'previous_response',
  lastError: null
});

assert.equal(result.previousResponseId, 'resp_test');
assert.ok(capturedOptions, 'provider options should be captured');
assert.equal(capturedOptions.metadata.purpose, 'agentic_decision');
assert.equal(capturedOptions.metadata.step, '7');
assert.equal(typeof capturedOptions.metadata.step, 'string');
assert.equal(capturedOptions.reasoningEffort, 'low');
assert.equal(capturedOptions.maxTokens, 123);
assert.equal(capturedOptions.previousResponseId, 'previous_response');
assert.equal(capturedOptions.images.length, 1);
